function compareCandidate(candidate: Candidate, k: number): -1 | 0 | 1 {
  if (candidate.kind === 'linear') {
    const d = candidate.value - k;
    return d > 0 ? 1 : d < 0 ? -1 : 0;
  }
  const m = k + candidate.c;
  if (m < 0) return 1; // sqrt(n) >= 0 > m
  const d = candidate.n - m * m;
  return d > 0 ? 1 : d < 0 ? -1 : 0;
}
